style.css:
@-moz-document domain("pinterest.com") {
/* --- Tema personalizado de Luná --- */
  :root {
    --azul-base: #1B365D;    /* PMS 534 C */
    --azul-escuro: #0f1724;
    --roxo-botao: #4B0082;   /* PMS 2627 C */
    --cinza-claro: #dcdcdc;
  }

  /* fundo geral */
  body {
    background-color: var(--azul-base) !important;
    color: var(--cinza-claro) !important;
    font-family: "Inter", "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial !important;
  }

  /* ---------------------------
     barras: lateral e superior
     ---------------------------*/
  header,
  nav[role="navigation"],
  [data-test-id="header"],
  [data-test-id="desktop-nav"] {
    background-color: var(--azul-escuro) !important;
  }

  aside,
  [data-test-id="left-rail"],
  [data-test-id="navigation-bar"],
  nav {
    background-color: var(--azul-escuro) !important;
  }

  /* ---------------------------
     campo de pesquisa
     ---------------------------*/
  input[type="search"],
  input[aria-label*="search"],
  [data-test-id="search-bar"],
  [data-test-id="search-input"] {
    background-color: var(--cinza-claro) !important;
    color: var(--azul-base) !important;
    border-radius: 12px !important;
    border: none !important;
  }

  input::placeholder,
  input[placeholder] {
    color: var(--azul-base) !important;
    opacity: 0.85 !important;
  }

  [data-test-id="search-bar"] > div,
  .searchBox,
  .ui-searchbox {
    background-color: transparent !important;
  }

  /* ---------------------------
     botões e ícones
     ---------------------------*/
  button,
  [role="button"],
  .button,
  .btn {
    background-color: var(--roxo-botao) !important;
    color: var(--cinza-claro) !important;
    border-radius: 12px !important;
    transition: background-color 0.18s ease, box-shadow 0.18s ease;
  }

  button:hover,
  [role="button"]:hover,
  .button:hover {
    background-color: #5E0FA3 !important; /* versão mais clara do roxo para hover */
    box-shadow: 0 0 8px rgba(0,0,0,0.15) !important;
  }

  /* ---------------------------
     pins / cards
     ---------------------------*/
  div[data-test-id="pin"],
  .Pin,
  [data-grid-item] {
    background-color: var(--azul-escuro) !important;
    border-radius: 16px !important;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
  }

  div[data-test-id="pin"]:hover,
  .Pin:hover {
    transform: translateY(-3px) !important;
    box-shadow: 0 6px 20px rgba(0,0,0,0.25) !important;
  }

  /* textos e links */
  a, a * {
    color: var(--cinza-claro) !important;
    text-decoration: none !important;
  }

  a:hover {
    text-decoration: underline !important;
  }

  /* evitar fundos brancos */
  * {
    background: transparent !important;
  }

  [style*="background-color: rgb"], 
  [style*="background-color: #"] {
    color: var(--cinza-claro) !important;
  }
}
